module evenland (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire edge_valid,\n    input wire [3:0] N,\n    input wire [4:0] M,\n    input wire [2:0] edge_a,\n    input wire [2:0] edge_b,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // Maximum sizes (for synthesis)\n    localparam MAX_N = 8;\n    localparam MAX_M = 16;\n\n    // State definitions\n    localparam [3:0] IDLE           = 4'd0;\n    localparam [3:0] COLLECT        = 4'd1;\n    localparam [3:0] FIND           = 4'd2;\n    localparam [3:0] PROCESS_RESULT = 4'd3;\n    localparam [3:0] UNION          = 4'd4;\n    localparam [3:0] CHECK_DONE     = 4'd5;\n    localparam [3:0] COMPUTE_INIT   = 4'd6;\n    localparam [3:0] COMPUTE_LOOP   = 4'd7;\n    localparam [3:0] COMPUTE_RESULT = 4'd8;\n    localparam [3:0] OUTPUT_DONE    = 4'd9;\n\n    // Registers\n    reg [3:0] state;\n    reg [3:0] next_state;\n    reg [3:0] parent [0:MAX_N-1];       // Parent for each vertex\n    reg [4:0] edge_count;               // Edges processed\n    reg [4:0] M_reg;\n    reg [3:0] N_reg;\n    reg [2:0] temp_a, temp_b;\n    reg [2:0] find_target;\n    reg [2:0] root_a, root_b;\n    reg [2:0] root_temp;\n    reg [1:0] phase;\n    reg [2:0] find_iter;\n    reg [3:0] i;\n    reg [3:0] component_count; \n    reg [31:0] shift_amount; \n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE:           if (start) next_state = COMPUTE_INIT;\n            COMPUTE_INIT:   next_state = COLLECT;\n            COLLECT: begin\n                if (edge_count < M_reg && edge_valid) next_state = FIND;\n                else if (edge_count == M_reg) next_state = COMPUTE_LOOP;\n            end\n            FIND: begin\n                if (parent[find_target] == find_target) next_state = PROCESS_RESULT;\n                else if (find_iter >= 3'd7) next_state = PROCESS_RESULT;\n            end\n            PROCESS_RESULT: begin\n                if (phase == 2'd1) next_state = FIND;\n                else if (phase == 2'd2) next_state = UNION;\n                else if (phase == 2'd3) next_state = COMPUTE_LOOP;\n            end\n            UNION:          next_state = CHECK_DONE;\n            CHECK_DONE: begin\n                if (edge_count == M_reg) next_state = COMPUTE_LOOP;\n                else next_state = COLLECT;\n            end\n            COMPUTE_LOOP: begin\n                if (i >= N_reg) next_state = COMPUTE_RESULT;\n                else next_state = FIND;\n            end\n            COMPUTE_RESULT: next_state = OUTPUT_DONE;\n            OUTPUT_DONE:    next_state = IDLE;\n            default:        next_state = IDLE;\n        endcase\n    end\n\n    // Sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            edge_count <= 5'd0;\n            parent[0] <= 4'd0;\n            parent[1] <= 4'd1;\n            parent[2] <= 4'd2;\n            parent[3] <= 4'd3;\n            parent[4] <= 4'd4;\n            parent[5] <= 4'd5;\n            parent[6] <= 4'd6;\n            parent[7] <= 4'd7;\n            M_reg <= 5'd0;\n            N_reg <= 4'd0;\n            component_count <= 4'd0;\n            phase <= 2'd0;\n            shift_amount <= 32'd0;\n        end else begin\n            state <= next_state;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        parent[0] <= 4'd0;\n                        parent[1] <= 4'd1;\n                        parent[2] <= 4'd2;\n                        parent[3] <= 4'd3;\n                        parent[4] <= 4'd4;\n                        parent[5] <= 4'd5;\n                        parent[6] <= 4'd6;\n                        parent[7] <= 4'd7;\n                        M_reg <= M;\n                        N_reg <= N;\n                        edge_count <= 5'd0;\n                    end\n                end\n                \n                COMPUTE_INIT: begin\n                    i <= 4'd0;\n                    component_count <= 4'd0;\n                end\n\n                COLLECT: begin\n                    if (edge_count < M_reg && edge_valid) begin\n                        temp_a <= edge_a - 3'd1;\n                        temp_b <= edge_b - 3'd1;\n                        edge_count <= edge_count + 5'd1;\n                        phase <= 2'd1;\n                        find_target <= edge_a - 3'd1;\n                        find_iter <= 3'd0;\n                    end\n                end\n\n                FIND: begin\n                    if (parent[find_target] != find_target) begin\n                        find_target <= parent[find_target];\n                        find_iter <= find_iter + 3'd1;\n                    end\n                end\n\n                PROCESS_RESULT: begin\n                    if (phase == 2'd1) begin\n                        root_a <= root_temp;\n                        phase <= 2'd2;\n                        find_target <= temp_b;\n                        find_iter <= 3'd0;\n                    end else if (phase == 2'd2) begin\n                        root_b <= root_temp;\n                        phase <= 2'd3;\n                    end else if (phase == 2'd3) begin\n                        component_count <= component_count + 4'd1;\n                        i <= i + 4'd1;\n                    end\n                end\n\n                UNION: begin\n                    if (root_a != root_b) begin\n                        parent[root_a] <= root_b;\n                    end\n                end\n\n                CHECK_DONE: ;\n\n                COMPUTE_LOOP: begin\n                    if (i < N_reg) begin\n                        phase <= 2'd3;\n                        find_target <= i;\n                        find_iter <= 3'd0;\n                    end \n                end\n\n                COMPUTE_RESULT: begin\n                    shift_amount <= M_reg + component_count - N_reg;\n                end\n\n                OUTPUT_DONE: begin\n                    result <= 32'h1 << shift_amount;\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\n\nendmodule